    TNode_* CreateNode_(TNode_* next, TNode_* prev, const T& value)
    {
        TNode_* ret
            = (TNode_*)mAllocator.AllocateRaw(sizeof(TNode_) + sizeof(T));

        // This is really dumb but it stops CreateNode_ from being inlined in
        // TList_pointer_void::iterator TList_pointer_void::insert.
        // Might be some leftover debug message/assert.
        (void)next;
        (void)prev;
        (void)value;

        if (!ret)
            return nullptr;

        ret->mNext = next;
        ret->mPrev = prev;
        mAllocator.construct((T*)(ret + 1), value); // the store happens here where the issue presents itself
        return ret;
    }
