    iterator insert(iterator where, const T& what)
    {
        TNode_* current = where.mNode;
        TNode_* prev    = current->mPrev;
        TNode_* newNode = CreateNode_(current, prev, what);

        if (newNode == nullptr) {
            // Casting this as iterator(end()) fixes stack issues in TList_pointer_void::insert
            // but this function itself.
            // return iterator(end());
            return iterator(end());
        }

        current->mPrev = newNode;
        prev->mNext    = newNode;
        ++mSize;
        return iterator(newNode);
    }
